diff --git a/matmul.cu b/matmul.cu
--- a/matmul.cu
+++ b/matmul.cu
@@ -1,12 +1,25 @@
+#define TILE 16
 extern "C" __global__ void square_matrix_mul(const int* a, const int* b, int* c, int n) {
+    __shared__ int tile_a[TILE][TILE];
+    __shared__ int tile_b[TILE][TILE];
     int row = blockIdx.y * blockDim.y + threadIdx.y;
     int column = blockIdx.x * blockDim.x + threadIdx.x;
-    if (row >= n || column >= n) {
-        return;
-    }
     int sum = 0;
-    for (int k = 0; k < n; ++k) {
-        sum += a[row * n + k] * b[k * n + column];
+    for (int base = 0; base < n; base += TILE) {
+        int k_a = base + threadIdx.x;
+        int k_b = base + threadIdx.y;
+        tile_a[threadIdx.y][threadIdx.x] = (row < n && k_a < n) ? a[row * n + k_a] : 0;
+        tile_b[threadIdx.y][threadIdx.x] = (k_b < n && column < n) ? b[k_b * n + column] : 0;
+        __syncthreads();
+        for (int k = 0; k < TILE; ++k) {
+            sum += tile_a[threadIdx.y][k] * tile_b[k][threadIdx.x];
+        }
+        __syncthreads();
+    }
+    if (row < n && column < n) {
+        c[row * n + column] = sum;
     }
-    c[row * n + column] = sum;
 }

